import unittest

from config import get_setting


class ConfigTests(unittest.TestCase):
    def setUp(self):
        self.config = {'model': {'name': 'demo', 'limits': {'steps': 8}}}

    def test_nested_value(self):
        self.assertEqual(get_setting(self.config, 'model.name'), 'demo')

    def test_deep_value(self):
        self.assertEqual(get_setting(self.config, 'model.limits.steps'), 8)

    def test_missing_value(self):
        self.assertEqual(get_setting(self.config, 'model.unknown', 'fallback'), 'fallback')


if __name__ == '__main__':
    unittest.main()
